import{analyze}from'./engine.mjs';
const $=id=>document.getElementById(id);let report=null,companion=false;
$('help').onclick=()=>$('limits').showModal();$('close').onclick=()=>$('limits').close();
const clear=()=>{report=null;$('results').hidden=true;$('plan-results').replaceChildren();$('error').textContent='';};
for(const id of ['before','after']){$(id).oninput=clear;$(id+'-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;clear();if(f.size>500000){$('error').textContent='Each specification must be under 500 KB.';return;}$(id).value=await f.text();};}
$('example').onclick=async()=>{try{const specs=await Promise.all(['before','after'].map(id=>fetch(id+'.json').then(r=>r.json())));clear();['before','after'].forEach((id,i)=>$(id).value=JSON.stringify(specs[i],null,2));}catch{$('error').textContent='Example could not load. Import two OpenAPI 3 JSON files instead.';}};
$('compare').onclick=async()=>{clear();try{const specs=['before','after'].map(id=>{if(new TextEncoder().encode($(id).value).length>500000)throw Error('Each specification must be under 500 KB.');return JSON.parse($(id).value);});report=await analyze(...specs);$('summary').textContent=report.breaking_count?`${report.breaking_count} potential breaking changes`:'No supported breaking changes detected';$('changes').replaceChildren();report.changes.forEach((c,i)=>{const card=document.createElement('article');card.className='change';const num=document.createElement('span');num.className='number';num.textContent=i+1;const body=document.createElement('div');const h=document.createElement('h3');h.textContent=c.message;const code=document.createElement('code');code.textContent=c.pointer;const ref=document.createElement('p');ref.textContent='Change '+c.id;body.append(h,code,ref);card.append(num,body);$('changes').append(card);});$('results').hidden=false;$('plan').disabled=!companion||!report.breaking_count;$('plan-status').textContent=companion?'Only change descriptions are sent to Nebius when you request a plan.':'For live Nemotron planning, run python3 server.py from the test build with Nebius credentials configured. This preview performs local analysis only.';}catch(e){$('error').textContent=e.message;}};
$('plan').onclick=async()=>{if(!report)return;$('plan').disabled=true;$('plan-status').textContent='Nemotron is drafting a migration plan…';try{const r=await fetch('/api/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({before:JSON.parse($('before').value),after:JSON.parse($('after').value)})});const data=await r.json();if(!r.ok)throw Error(data.error||'Inference failed.');report.migration=data;$('plan-results').replaceChildren();data.steps.forEach((s,i)=>{const el=document.createElement('div');el.className='step';const p=document.createElement('p');p.textContent=`${i+1}. ${s.action}`;const ref=document.createElement('code');ref.textContent=s.change_ids.join(' · ');el.append(p,ref);$('plan-results').append(el);});$('plan-status').textContent=`${data.provider} / ${data.model} · ${data.duration_ms} ms. References checked; review all advice. No tests executed.`;}catch(e){$('plan-status').textContent=e.message;}finally{$('plan').disabled=false;}};
$('export').onclick=()=>{if(!report)return;const u=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='contractpilot-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
fetch('/api/status').then(r=>r.ok?r.json():null).then(s=>{if(s?.live_ready){companion=true;$('mode').textContent='Nebius model configured';$('mode-note').textContent='Analysis stays local. Request a migration plan to send detected change descriptions to NVIDIA Nemotron on Nebius.';}}).catch(()=>{});
